package com.fitnutri.backend.domain;
import com.fasterxml.jackson.databind.*;
import com.fitnutri.backend.activity.*;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.summary.*;
import com.fitnutri.backend.summary.SummaryModels.*;
import java.math.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Same independently fixed synthetic vectors consumed by frontend contract/input tests. */
class SharedCalculationFixtureTest {
    final JsonNode fixture;
    SharedCalculationFixtureTest() throws Exception {fixture=new ObjectMapper().readTree(Files.readAllBytes(Path.of("..","tests","fixtures","calculations.json")));}
    BigDecimal decimal(JsonNode value){return value==null||value.isNull()?null:new BigDecimal(value.asText());}
    RecordDatePolicy dates(){return new RecordDatePolicy(Clock.fixed(Instant.parse(fixture.get("clockInstant").asText()),ZoneOffset.UTC),new ZoneResolver(fixture.get("zone").asText()));}
    FoodReference food(JsonNode vector){var d=new FoodDataset();d.setId(301L);d.setName("SYNTHETIC_Q01_ONLY");d.setRelease("test");d.setRevision("one");d.setVerified(true);d.setContentSha256("a".repeat(64));var f=new FoodReference();f.setId(Long.valueOf(vector.get("referenceId").asText()));f.setDataset(d);f.setActive(true);f.setDisplayName("Synthetic Q01 food");f.setEnergyKj100g(decimal(vector.get("per100g").get("energyKj")));f.setProteinG100g(decimal(vector.get("per100g").get("proteinGrams")));f.setFatG100g(decimal(vector.get("per100g").get("fatGrams")));f.setCarbsG100g(decimal(vector.get("per100g").get("carbsGrams")));return f;}
    @Test void portionResultsAndLargeOpaqueIdMatchSharedDecimalVectors(){var calculator=new FoodCalculationService();for(var v:fixture.get("foods")){var p=calculator.preview(food(v),decimal(v.get("grams")));var e=v.get("expected");assertEquals(v.get("referenceId").asText(),p.reference().referenceId());assertEquals(decimal(e.get("energyKj")),p.nutrients().energyKj(),v.get("id").asText());assertEquals(decimal(e.get("proteinGrams")),p.nutrients().proteinGrams());assertEquals(decimal(e.get("fatGrams")),p.nutrients().fatGrams());assertEquals(decimal(e.get("carbsGrams")),p.nutrients().carbsGrams());assertTrue(p.calculationFingerprint().matches("[a-f0-9]{64}"));}}
    @Test void invalidGramsAndMissingCoreAreRejectedInsteadOfRoundedOrZeroFilled(){var calculator=new FoodCalculationService();for(var grams:fixture.get("invalidGrams"))assertThrows(BusinessException.class,()->calculator.calculate(food(fixture.get("foods").get(0)),decimal(grams)),grams.asText());var f=food(fixture.get("foods").get(0));f.setProteinG100g(null);assertEquals("UNSUPPORTED_REFERENCE",assertThrows(BusinessException.class,()->calculator.calculate(f,BigDecimal.TEN)).code());}
    @Test void datedSyntheticMetAndNullOutcomesMatchTheSameFrontendPreviewVectors(){for(var v:fixture.get("exercise")){var catalogue=mock(ExerciseCatalog.class);var profiles=mock(ProfileService.class);var weights=mock(WeightEntryRepository.class);var dataset=new ActivityDataset();dataset.setId(302L);dataset.setName("SYNTHETIC_Q01_ONLY");dataset.setRelease("test");dataset.setRevision("one");dataset.setVerified(true);dataset.setContentSha256("b".repeat(64));dataset.setMinAge(19);dataset.setMaxAge(59);var type=new ExerciseType();type.setId(Long.valueOf(v.get("exerciseTypeId").asText()));type.setDataset(dataset);type.setActive(true);type.setActivityKey("synthetic-q01");type.setDisplayName("Synthetic Q01 activity");type.setSourceActivityCode("99901");type.setSourceDescription("Synthetic unit test only");type.setMetValue(decimal(v.get("met")));var profile=new UserProfile();profile.setBirthYear(v.get("birthYear").asInt());profile.setAdultConfirmed(true);profile.setOnboardingCompleted(true);var day=LocalDate.parse(v.get("recordDate").asText());when(catalogue.requireImmutable(type.getId())).thenReturn(type);when(profiles.requireCompletedAdultSetup(1L)).thenReturn(profile);if(!v.get("weightKg").isNull()){var w=new WeightEntry();w.setWeightKg(decimal(v.get("weightKg")));w.setEntryDate(LocalDate.parse(v.get("weightDate").asText()));when(weights.findFirstByUserIdAndEntryDateLessThanEqualOrderByEntryDateDesc(1L,day)).thenReturn(Optional.of(w));}var result=new ExerciseEstimateService(catalogue,profiles,weights,dates()).estimate(1L,type.getId(),day,decimal(v.get("minutes")),fixture.get("zone").asText());assertEquals(v.get("expectedStatus").asText(),result.estimateStatus().name(),v.get("id").asText());assertEquals(decimal(v.get("expectedKj")),result.estimatedKj());assertEquals(v.get("exerciseTypeId").asText(),result.exerciseType().id());if(result.estimateStatus()==EstimateStatus.AVAILABLE){assertEquals(decimal(v.get("weightKg")),result.weightKgUsed());assertEquals(LocalDate.parse(v.get("weightDate").asText()),result.weightDateUsed());verify(weights).findFirstByUserIdAndEntryDateLessThanEqualOrderByEntryDateDesc(1L,day);}else{assertNull(result.weightKgUsed());assertNull(result.weightDateUsed());assertNull(result.metUsed());}if(result.estimateStatus()==EstimateStatus.NO_APPLICABLE_REFERENCE)verifyNoInteractions(weights);}}
    @Test void fixedSydneyCalendarRejectsFutureAndImpossibleDates(){var dates=dates();assertEquals(fixture.get("today").asText(),dates.today(fixture.get("zone").asText()).toString());for(var v:fixture.get("dates")){if(v.get("valid").asBoolean())assertEquals(v.get("value").asText(),dates.requireDate(LocalDate.parse(v.get("value").asText()),fixture.get("zone").asText()).toString());else if(v.get("failure").asText().equals("INVALID_CALENDAR"))assertThrows(java.time.format.DateTimeParseException.class,()->LocalDate.parse(v.get("value").asText()));else assertEquals("VALIDATION_ERROR",assertThrows(BusinessException.class,()->dates.requireDate(LocalDate.parse(v.get("value").asText()),fixture.get("zone").asText())).code());}}
    @Test void allSharedSafetyAnswersAndConsentCombinationsUseTheActualServerRule(){for(var v:fixture.get("eligibility")){var p=new UserProfile();p.setHealthSafetyAnswer(v.get("answer").isNull()?null:HealthSafetyAnswer.valueOf(v.get("answer").asText()));p.setHealthSafetyConsent(v.get("consent").asBoolean());assertEquals(v.get("eligible").asBoolean(),QaEligibility.isEligible(p),v.toString());}assertFalse(QaEligibility.isEligible(null));}
    @Test void sharedHundredMissingZeroAbsentSeriesUsesTwoKnownDaysAndNoImplicitTarget(){var v=fixture.get("summary");var from=LocalDate.parse(v.get("from").asText());var to=LocalDate.parse(v.get("to").asText());var repository=mock(SummaryRepository.class);var profiles=mock(UserProfileRepository.class);var weights=mock(WeightEntryRepository.class);var rows=new ArrayList<SummaryRepository.FoodDay>();for(var day:v.get("intake")){if(!day.get("hasRecord").asBoolean())continue;BigDecimal value=decimal(day.get("knownKj"));var intake=MetricAggregate.of(1,value==null?0:1,value,0);var unavailable=MetricAggregate.of(1,0,null,0);rows.add(new SummaryRepository.FoodDay(LocalDate.parse(day.get("date").asText()),1,intake,unavailable,unavailable,unavailable));}when(repository.foodDays(1L,from.minusDays(v.get("calendarDayCount").asInt()),to)).thenReturn(rows);var result=new SummaryService(repository,profiles,weights,dates(),new RuleSummaryService()).period(1L,from,to,fixture.get("zone").asText());assertEquals(decimal(v.get("expectedKnownTotal")),result.totals().intake().knownSum());assertEquals(decimal(v.get("expectedAverage")),result.averages().intake().value());assertEquals(v.get("knownDayCount").asInt(),result.averages().intake().knownDayCount());assertEquals(v.get("recordCount").asInt(),result.totals().intake().recordCount());assertEquals(v.get("missingValueCount").asInt(),result.totals().intake().missingValueCount());assertTrue(result.totals().intake().partial());assertNull(result.days().get(1).intake().knownSum());assertTrue(result.days().get(1).intake().hasData());assertEquals(new BigDecimal("0.000"),result.days().get(2).intake().knownSum());assertFalse(result.days().get(3).intake().hasData());assertNull(result.goalComparison());}
}
